/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_products_insert` AFTER INSERT ON `tb_products` FOR EACH ROW BEGIN
    INSERT INTO tb_logs (
        table_name,
        table_operation,
        db_user,
        operation_description,
        operation_date,
        operation_status
    )
    VALUES (
        'tb_products',
        'Create',
        SUBSTRING_INDEX(USER(), '@', 1),
        CONCAT(
            'Producto creado. ID=', NEW.ID,
            ', SKU=', NEW.SKU,
            ', Nombre=', NEW.name,
            ', Precio=', NEW.current_price,
            ', Stock=', NEW.current_stock
        ),
        NOW(),
        b'1'
    );
END */;;
